<script setup>
import AccountPicker from './AccountPicker.vue';
import TablePanel from '../../shared/components/TablePanel.vue';

import { vMoney } from './money-input.js';
import {computed,inject,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue';
import {accountTypes,amount,decimal,downloadRows,errorText,financeKey,matchesAccount,minor,money,positive,sum,transferRows} from './finance-model.js';
import FinancePagination from './FinancePagination.vue';
import FinanceDialog from './FinanceDialog.vue';
const vm=inject(financeKey),query=ref(''),selected=ref([]),drafts=reactive({}),reference=ref(''),text=ref(''),reading=ref(false),preview=ref(null),result=ref(null),from=ref(vm.admin.value?'':vm.ownId.value),importedRows=ref([]),key=vm.key();
let importRevision=0;
onBeforeUnmount(()=>{importRevision++;});
const list=vm.resource('accounts'),allowedIds=ref(new Set()),recipientPage=ref(1);
const choices=computed(()=>vm.options.accounts.filter(row=>allowedIds.value.has(Number(row.id)))),recipients=computed(()=>list.state.rows);
async function loadRecipients(page=1){if(!from.value){list.dispose();return;}recipientPage.value=page;await list.load({ancestor_id:from.value,exclude_account_id:from.value,account_status:'active',account_query:query.value,...(vm.service.value==='topup'?{account_types:['pos']}:{}),per_page:25,page});vm.rememberAccounts(list.state.rows);list.state.rows.forEach(row=>allowedIds.value.add(Number(row.id)));}
watch([from,()=>vm.balanceGeneration.value],([id])=>{if(id)void vm.loadWallets(undefined,[id]);});
let searchTimer;watch(query,()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>loadRecipients(),300);});watch(from,()=>{allowedIds.value=new Set();loadRecipients();});onMounted(()=>loadRecipients());onBeforeUnmount(()=>clearTimeout(searchTimer));
const available=computed(()=>from.value?vm.walletAmount(from.value,vm.service.value,vm.currency.value):null);
function clear(){selected.value=[];Object.keys(drafts).forEach(id=>delete drafts[id]);text.value='';importedRows.value=[];preview.value=null;result.value=null;key.clear();}
watch(from,()=>{importRevision++;clear();});
watch([vm.service,vm.currency],()=>{importRevision++;preview.value=null;result.value=null;allowedIds.value=new Set();void loadRecipients();});
async function importRows(rows){const expectedImport=importRevision,expectedFrom=from.value;const ids=[...new Set(rows.filter(cells=>cells.some(Boolean)&&! /^(?:المستفيد|معرف|account_id|to_account_id)$/i.test(String(cells[0]).trim())).map(cells=>Number(cells[0])))];if(ids.length>100||ids.some(id=>!Number.isSafeInteger(id)||id<=0))throw Error('القائمة يجب أن تحتوي حتى 100 حساب صحيح.');const lookup=await vm.api.list('accounts',{lookup_ids:ids,ancestor_id:from.value,exclude_account_id:from.value,account_status:'active',per_page:100});if(expectedImport!==importRevision||expectedFrom!==from.value)throw Error('تغير الممول أو الصفحة؛ أعد الاستيراد.');if(lookup.data.length!==ids.length)throw Error('بعض الحسابات غير متاحة للتمويل.');vm.rememberAccounts(lookup.data);lookup.data.forEach(row=>allowedIds.value.add(Number(row.id)));const incoming=[],amounts={},keys=new Set();for(const cells of rows){if(!cells.some(Boolean))continue;if(/^(?:المستفيد|معرف|account_id|to_account_id)$/i.test(String(cells[0]).trim()))continue;const id=Number(cells[0]),service=cells[2] || vm.service.value,currency=cells[4] || vm.currency.value;if(!Number.isSafeInteger(id) || !choices.value.some(account=>account.id===id))throw new Error(`المستفيد ${cells[0]} غير متاح للتمويل.`);if(service==='topup'&&!lookup.data.some(account=>Number(account.id)===id&&account.type==='pos'))throw new Error('تمويل Topup من الوكيل الرئيسي إلى نقطة بيع تابعة فقط.');if(!vm.options.services.some(row=>row.id===service) || !vm.options.currencies.includes(currency))throw new Error('المحفظة أو العملة في الملف غير متاحة.');const identity=`${id}:${service}:${currency}`;if(keys.has(identity))throw new Error(`المستفيد #${id} مكرر في المحفظة نفسها.`);keys.add(identity);const value=amount(cells[1]);incoming.push({to_account_id:id,amount:value,service,currency,...(cells[3]?{reference:cells[3]}:{})});amounts[id]=value;}if(!incoming.length || incoming.length>100)throw new Error('القائمة يجب أن تحتوي من 1 إلى100 صف.');importedRows.value=incoming;selected.value=[...new Set(incoming.map(row=>row.to_account_id))];Object.keys(drafts).forEach(id=>delete drafts[id]);Object.assign(drafts,amounts);}
async function readFile(event){const file=event.target.files?.[0];event.target.value='';if(!file || reading.value || vm.busy.value)return;reading.value=true;vm.error.value='';const revision=importRevision;try{const {readImportFile}=await import('../../shared/files/import-reader.js');const sheets=await readImportFile(file);if(revision!==importRevision)throw new Error('تغير الممول أو المحفظة أو الصفحة؛ أعد الاستيراد.');await importRows(sheets.flatMap(sheet=>sheet.rows));text.value='';}catch(failed){if(revision===importRevision)vm.error.value=errorText(failed);}finally{reading.value=false;}}
async function prepare(){vm.error.value='';try{if(!from.value)throw new Error('اختر الوكيل الممول.');if(!vm.service.value)throw new Error('اختر محفظة محددة للتمويل.');const fundingSource=from.value;const refreshed=await vm.loadWallets(undefined,[fundingSource],{fresh:true});if(!Array.isArray(refreshed))throw new Error(vm.balancesError.value || 'تعذر استعلام الرصيد الحالي؛ أعد المعاينة.');if(fundingSource!==from.value)throw new Error('تغير الوكيل الممول؛ أعد المعاينة.');if(vm.balancesError.value)throw new Error(vm.balancesError.value);if(text.value.trim()){const {delimited}=await import('../../shared/files/import-reader.js');await importRows(delimited(text.value));}if(!reference.value.trim())throw new Error('أدخل مرجع المجموعة.');if(!importedRows.value.length&&selected.value.length){const expected=importRevision,source=from.value;if(selected.value.length>100)throw new Error('القائمة يجب أن تحتوي حتى 100 حساب صحيح.');const result=await vm.api.list('accounts',{lookup_ids:selected.value,ancestor_id:source,exclude_account_id:source,account_status:'active',per_page:100});if(expected!==importRevision||source!==from.value)throw new Error('تغير الممول أو الصفحة؛ أعد الاختيار.');const found=new Set(result.data.map(row=>Number(row.id)));if(selected.value.some(id=>!found.has(Number(id))))throw new Error('بعض الحسابات غير متاحة للتمويل.');vm.rememberAccounts(result.data);result.data.forEach(row=>allowedIds.value.add(Number(row.id)));}const rows=importedRows.value.length?importedRows.value:transferRows(selected.value,drafts,choices.value),groups=new Map();for(const row of rows){const service=row.service || vm.service.value,currency=row.currency || vm.currency.value,id=`${service}:${currency}`;if(!groups.has(id))groups.set(id,{service,currency,values:[]});groups.get(id).values.push(row.amount);}if(groups.has('topup:IQD')&&!vm.options.accounts.some(account=>Number(account.id)===Number(fundingSource)&&account.type==='main_agent'))throw new Error('تمويل Topup من الوكيل الرئيسي إلى نقطة بيع تابعة فقط.');if(rows.some(row=>(row.service||vm.service.value)==='topup'&&!vm.options.accounts.some(account=>Number(account.id)===Number(row.to_account_id)&&account.type==='pos')))throw new Error('تمويل Topup من الوكيل الرئيسي إلى نقطة بيع تابعة فقط.');const balances=[...groups.values()].map(row=>{const available=sum(refreshed.filter(wallet=>Number(wallet.account_id)===Number(fundingSource)&&wallet.service===row.service&&wallet.currency===row.currency).map(wallet=>wallet.available));const total=sum(row.values);return{service:row.service,currency:row.currency,total,available,remaining:decimal(minor(available)-minor(total))};});preview.value={rows:rows.map(row=>({...row})),from:Number(from.value),service:vm.service.value,currency:vm.currency.value,reference:reference.value.trim(),balances,valid:balances.every(row=>minor(row.remaining)>=0n)};}catch(failed){vm.error.value=errorText(failed);}}
async function confirm(){if(!preview.value?.valid)return;const payload={from_account_id:preview.value.from,service:preview.value.service,currency:preview.value.currency,reference:preview.value.reference,rows:preview.value.rows};const response=await vm.execute(payload,key,body=>vm.api.create('bulk-transfers',body),'تم تنفيذ مجموعة التمويل.');if(response){result.value={...preview.value,response:response.data};preview.value=null;selected.value=[];Object.keys(drafts).forEach(id=>delete drafts[id]);text.value='';importedRows.value=[];await vm.refresh();}}
function downloadPreview(data=preview.value || result.value){if(!data)return;downloadRows('masal-funding.csv',[['المستفيد','المحفظة','المبلغ','العملة','مرجع الطلب','النتيجة','السبب','رقم العملية'],...data.rows.map(row=>{const transfer=data.response?.find(item=>item.to_account_id===row.to_account_id && item.service===(row.service || data.service) && item.currency===(row.currency || data.currency));return[vm.name(row.to_account_id),vm.serviceName(row.service || data.service),row.amount,row.currency || data.currency,row.reference || data.reference,transfer?'منفذ':'معاينة',data.valid?'':'الرصيد لا يكفي لكامل المجموعة',transfer?.transaction_id ?? ''];})]);}
</script>
<template><div class="card"><div class="bulk-funding-toolbar"><label>الممول<AccountPicker v-model="from" :vm="vm" :parameters="{...(vm.admin.value?{account_types:vm.service.value==='topup'?['main_agent']:['main_agent','sub_agent','sub_branch']}:{account_id:vm.ownId.value}),account_status:'active'}" label="الممول للتمويل المتعدد" :clearable="false"/></label><label>بحث باسم المستفيد<input v-model="query" placeholder="اسم النقطة أو الوكيل أو المحافظة"></label></div><p class="help">حدد المستفيدين وأدخل مبلغ كل واحد، ثم اضغط معاينة المجموعة. المحفظة المستخدمة: {{vm.serviceName(vm.service.value) || 'اختر محفظة'}}.</p><TablePanel class="tablewrap" style="max-height:420px;overflow:auto"><table class="bulk-recipient-table"><thead><tr><th>اختيار</th><th>المستفيد</th><th>النوع</th><th>المبلغ • {{vm.currencyLabel(vm.currency.value)}}</th></tr></thead><tbody><tr v-for="row in recipients" :key="row.id"><td><input v-model="selected" type="checkbox" :value="row.id" :aria-label="'اختيار '+row.name" @change="text='';importedRows=[]"></td><td>{{row.name}}</td><td>{{accountTypes[row.type] || row.type}}</td><td><input v-model="drafts[row.id]" type="text" inputmode="decimal" v-money :disabled="!selected.includes(row.id) || vm.busy.value" :aria-label="'مبلغ '+row.name" placeholder="أدخل المبلغ" @input="importedRows=[];text=''"></td></tr><tr v-if="!recipients.length"><td colspan="4" class="empty">لا توجد جهات مطابقة متاحة للتمويل.</td></tr></tbody></table><p v-if="list.state.error" class="notice warn" role="alert">{{list.state.error}}</p></TablePanel><FinancePagination :meta="list.state.meta" :busy="list.state.loading" @page="loadRecipients"/><p>المستفيدون المحددون: {{selected.length}}</p><p v-if="importedRows.length" class="caption">{{importedRows.length}} صف مستورد؛ معاينة المجموعة تعرض المحفظة والعملة لكل صف.</p><label>مرجع الطلب / المجموعة<input v-model="reference" maxlength="200" required></label><details><summary>استيراد قائمة من ملف — اختياري</summary><label>استيراد المستفيد، المبلغ، المحفظة، مرجع الطلب<input type="file" accept=".xlsx,.csv,.txt,.tsv" :disabled="reading || vm.busy.value" @change="readFile"></label><textarea v-model="text" dir="ltr" rows="5" placeholder="12,25000&#10;15,50000" @input="selected=[];importedRows=[]"></textarea></details><div class="actions"><button class="btn primary" :disabled="vm.busy.value || reading" @click="prepare">{{reading?'جارٍ قراءة الملف…':'معاينة المجموعة'}}</button><button class="btn" :disabled="vm.busy.value" @click="clear">بدء مجموعة جديدة</button></div><section v-if="result" class="funding-group-result"><div class="rowline"><strong>تم تنفيذ التمويل · {{result.rows.length}} مستفيد</strong><span><span v-for="balance in result.balances" :key="balance.service+balance.currency">{{vm.serviceName(balance.service)}}: {{money(balance.total)}} {{vm.currencyLabel(balance.currency)}}</span></span><button class="btn" @click="downloadPreview(result)">تنزيل النتائج</button></div><div v-for="row in result.rows" :key="row.to_account_id+':'+(row.service || preview?.service || result?.service)+':'+(row.currency || preview?.currency || result?.currency)" class="rowline"><span>{{vm.name(row.to_account_id)}}</span><span>{{money(row.amount)}} {{vm.currencyLabel(row.currency || result.currency)}} · منفذ</span></div></section></div>
  <FinanceDialog :open="!!preview" title="معاينة مجموعة التمويل" :busy="vm.busy.value" @close="preview=null"><template v-if="preview"><p><b>الممول:</b> {{vm.name(preview.from)}}</p><TablePanel class="tablewrap"><table><thead><tr><th>المستفيد</th><th>المحفظة</th><th>المبلغ</th><th>مرجع الطلب</th><th>الفحص</th></tr></thead><tbody><tr v-for="row in preview.rows" :key="row.to_account_id+':'+(row.service || preview?.service || result?.service)+':'+(row.currency || preview?.currency || result?.currency)"><td>{{vm.name(row.to_account_id)}}</td><td>{{vm.serviceName(row.service || preview.service)}}</td><td>{{money(row.amount)}} {{vm.currencyLabel(row.currency || preview.currency)}}</td><td>{{row.reference || preview.reference}}</td><td>صالح</td></tr></tbody></table></TablePanel><div v-for="balance in preview.balances" :key="balance.service+balance.currency" class="rowline"><b>{{vm.serviceName(balance.service)}} · {{vm.currencyLabel(balance.currency)}}</b><span>الإجمالي: {{money(balance.total)}}</span><span>المتاح: {{money(balance.available)}}</span><span>المتبقي: {{money(balance.remaining)}}</span></div><p v-if="vm.error.value" class="notice warn" role="alert">{{vm.error.value}}</p><p v-else-if="!preview.valid" class="notice warn" role="alert">الرصيد لا يكفي لكامل المجموعة</p><div class="actions"><button class="btn primary" :disabled="!preview.valid || vm.busy.value" @click="confirm">تأكيد التمويل</button><button class="btn" @click="downloadPreview()">تنزيل الفحص</button><button class="btn" :disabled="vm.busy.value" @click="preview=null">إلغاء</button></div></template></FinanceDialog>
</template>
